const input=$json.body??$json;
const s=v=>String(v??"").trim();
const msg=s(input.message??input.seller_message??input.text);
const leadId=s(input.lead_id), dealId=s(input.deal_id), propertyId=s(input.property_id), threadId=s(input.thread_id);
const dnc=input.dnc===true||input.dnc_suppressed===true;
const missing=[];
if(!msg) missing.push("seller_message");
if(!leadId&&!dealId) missing.push("lead_id_or_deal_id");
if(!threadId) missing.push("thread_id");
let intent="unknown", motivation="unknown", objections=[], urgency="normal", posture="neutral";
const t=msg.toLowerCase();
if(/stop|remove me|do not (text|call)|dont (text|call)/.test(t)){intent="opt_out";urgency="critical";}
else if(/yes|interested|sounds good|lets do|send (it|me)|how much/.test(t)){intent="positive_interest";posture="cooperative";}
else if(/no|not interested|pass|decline|dont want|do not want/.test(t)){intent="negative_interest";posture="resistant";}
else if(/maybe|think about|not sure|later|call me back/.test(t)){intent="uncertain";posture="cautious";}
else if(/price|offer|too low|more money|higher/.test(t)){intent="negotiation";posture="negotiating";}
if(/move|moving|foreclosure|behind|tax|need to sell|divorce|inherited|estate|vacant|tenant/.test(t)) motivation="distress_or_timing";
if(/asap|today|tomorrow|this week|urgent|quickly/.test(t)) urgency="high";
if(/price|offer|too low|more money|higher/.test(t)) objections.push("price");
if(/condition|repair|needs work|fix/.test(t)) objections.push("property_condition");
if(/agent|realtor|commission|listing/.test(t)) objections.push("agent_or_listing");
if(/think|talk to|spouse|partner/.test(t)) objections.push("decision_process");
if(dnc||intent==="opt_out") intent="opt_out";
const autonomousCandidate=!dnc&&missing.length===0&&intent!=="opt_out"&&intent!=="unknown";
let reply="Thanks for the update. I want to make sure I understand what you need before suggesting anything.";
if(intent==="positive_interest") reply="Thanks for getting back to me. I can help with the next step. What works best for you—quick call or text?";
if(intent==="negotiation") reply="I hear you on the price. I want to make sure the numbers make sense for you and the property. What price were you hoping to get?";
if(intent==="uncertain") reply="No problem. What would you need to feel comfortable moving forward?";
if(intent==="negative_interest") reply="Understood. I appreciate you letting me know. If anything changes, you can reach back out.";
const actionId="seller-intelligence:"+((threadId||leadId||dealId||"unknown"))+":"+(input.request_id||input.audit_id||"message")+":v1";
return [{json:{ok:missing.length===0,analysis:{action_id:actionId,intent,motivation,objections,urgency,negotiation_posture:posture,summary:msg.slice(0,500),recommended_reply:reply,autonomous_response_candidate:autonomousCandidate,requires_human_review:dnc||missing.length>0||intent==="unknown"},identity:{lead_id:leadId||null,property_id:propertyId||null,deal_id:dealId||null,thread_id:threadId||null},routing:{next_workflow:autonomousCandidate?"wf-082-autonomous-communication-authorization-dispatch":intent==="opt_out"?null:"wf-078-ai-seller-conversation-response-intelligence",dispatch_mode:autonomousCandidate?"authorization_gate":"internal_analysis"},missing_requirements:missing}}];
